INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63327033', 63327033, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Belanja Jasa Lainnya Tenaga Pendukung Inspektorat Utama TA. 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 1680000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup Pekerjaan Jasa Lainnya Perorangan Tenaga Pendukung Inspektorat Utama Badan Gizi Nasional a. Administrasi Program dan Pelaporan Anggaran Meliputi dukungan pada: Penyusunan dokumen perencanaan dan penganggaran (RKA-K/L, Renja, Renstra, PKPT, PKAU, rencana kegiatan); Penyusunan indikator kinerja dan laporan kinerja (termasuk LKJiP); Monitoring dan evaluasi kinerja serta anggaran; Penginputan dan pengelolaan aplikasi SAKTI (role operator anggaran, komitmen, dan pembayaran); Penatausahaan administrasi perencanaan, keuangan, dan pelaporan; Pengarsipan, pengelolaan e-office, serta inventarisasi kebutuhan operasional; Dukungan pengelolaan BMN, pengadaan barang/jasa (SIMAN, SiRUP, InaProc), dan manajemen kontrak; Penyusunan laporan bulanan pelaksanaan tugas. b. Administrasi Pengelolaan Hasil Pengawasan dan Pengaduan Masyarakat Meliputi dukungan pada: Analisis dan monitoring tindak lanjut hasil pengawasan (Itama, BPK-RI, BPKP); Penginputan dan pemutakhiran data pada aplikasi SIMWAS; Penyusunan laporan kinerja tindak lanjut pengawasan; Pengelolaan dan verifikasi pengaduan masyarakat (SP4N-LAPOR!, Tawas Care, Sagi 127, dan surat); Klarifikasi, identifikasi, dokumentasi, serta penyusunan rekomendasi tindak lanjut aduan; Penyusunan laporan periodik pengaduan masyarakat; Penyusunan laporan bulanan pelaksanaan tugas. c. Administrasi SDM, Organisasi, dan Tata Laksana Meliputi dukungan pada: Pengelolaan SDM (Anjab, ABK, Peta Jabatan, IACM, pengembangan kompetensi); Pengelolaan data kepegawaian; Reformasi Birokrasi, SPIP, Zona Integritas, dan manajemen risiko; Pengelolaan dashboard dan portal Reformasi Birokrasi; Dukungan penyusunan produk hukum dan pengarsipannya; Pelayanan informasi dan kehumasan (website, media sosial, desain publikasi); Pelaksanaan survei kepuasan masyarakat; Penyusunan laporan bulanan pelaksanaan tugas.', 'Kualifikasi Personel a. Warga Negara Indonesia yang memiliki Nomor Induk Kependudukan (NIK); b. Memiliki NPWP (Nomor Pokok Wajib Pajak); c. Usia paling rendah 21 (dua puluh satu) tahun dan paling tinggi 45 (empat puluh lima) tahun ketika mendaftar; d. Pendidikan minimal Sarjana (S1) dengan IPK minimal 3,00; e. Tidak berkedudukan sebagai Calon ASN, ASN, prajurit TNI, atau anggota Kepolisian Negara RI; f. Memiliki integritas dan komitmen kerja yang tinggi; g. Mampu bekerja mandiri maupun dalam tim; h. Mampu berkomunikasi dengan baik; i. Mampu melakukan pekerjaan administrasi, analisis data dan informasi; j. Mahir dan terampil mengoperasikan komputer (minimal Ms. Office dan Internet); k. Berorientasi pada pelayanan publik dan memiliki inisiatif penuh dalam bekerja; l. Diutamakan mampu mengoperasikan aplikasi SAKTI dan SIMAN; m. Diutamakan yang memiliki pengalaman kerja paling sedikit 1 (satu) tahun, khususnya pada instansi pemerintah.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 860651);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62779845', 62779845, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Badan Pengelolaan Keuangan dan Aset Daerah', 'Penyedia Jasa Lainnya Orang Perseorangan Pelayanan TI', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 39084000, 'January 2026', 'APBD', 1, 1, '1 orang x 12 Bulan', 'a. Membantu transfer data dan memelihara database Pajak Daerah; b. Membantu pelaksanaan dan memaksimalkan e-SPTPD dan Sistem Monitoring, Pelaporan dan Pembayaran Pajak Daerah Secara Online dapat berjalan lancar; c. Membantu mempercepat penyelesaian permasalahan (troubleshooting) yang berkaitan dengan operasional SIM, hardware dan software yang berkaitan dengan Pajak Daerah dan Sistem Monitoring, Pelaporan dan Pembayaran Pajak Daerah Secara Online; d. Membantu meningkatkan sumber daya manusia pengguna SIM dan aplikasi yang berkaitan dengan Pajak Daerah; e. Membantu melaksanakan kustomisasi Aplikasi Pengelolaan Pajak Daerah; f. Memberikan pelayanan di Loket Pajak', 'S1 Pengalaman Kerja <15 Tahun Katagori A', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 860652);
