INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63328229', 63328229, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS KESEHATAN', 'Belanja Modal Lemari Pintu Ayun Kaca BLUD PUSKESMAS GAYAMSARI', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 5000000, 'October 2026', 'BLUD', 1, 1, '1 UNIT', 'Belanja Modal Lemari Pintu Ayun Kaca BLUD PUSKESMAS GAYAMSARI', 'Fitur Spesifikasi Detail Mekanisme Pintu Pintu Ayun (Swing Door): Menggunakan engsel yang memungkinkan pintu terbuka keluar. Membutuhkan ruang ekstra di depan lemari saat dibuka, tetapi memberikan akses penuh ke bagian dalam lemari. Bahan Rangka Plat Besi/Baja: Kokoh, tahan karat (dengan powder coating), anti rayap, dan tahan api (pada batas tertentu). Ideal untuk lemari arsip kantor. Kayu/MDF/Particle Board: Lebih ringan, menawarkan estetika hangat, sering digunakan untuk lemari pakaian atau lemari pajangan di rumah. Bahan Kaca Kaca Tempered: Kaca yang telah diperkuat, lebih aman karena jika pecah akan menjadi pecahan kecil tumpul. Ketebalan umum 4mm hingga 6mm. Kaca Biasa: Lebih umum pada model rumahan yang lebih terjangkau. Finishing Powder Coating (Besi): Lapisan cat oven yang tahan gores dan karat. HPL/Melamine (Kayu): Tahan kelembapan dan mudah dibersihkan. Fitur Tambahan Kunci: Umumnya tersedia kunci standar untuk keamanan dokumen atau barang berharga. Rak: Rak di dalamnya biasanya dapat diatur ketinggiannya (adjustable shelves). Desain Full Kaca: Seluruh bagian pintu adalah kaca. Kombinasi: Bagian bawah pintu plat besi, bagian atas kaca (lemari arsip kantor).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 861893);
