INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63327929', 63327929, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS KESEHATAN', 'Belanja Modal Meja Kerja BLUD PUSKESMAS GAYAMSARI', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 44000000, 'September 2026', 'BLUD', 1, 1, '11 UNIT', 'Belanja Modal Meja Kerja BLUD PUSKESMAS GAYAMSARI', 'Bahan Utama Particle Board atau MDF (sering dengan finishing HPL/melamine), Kayu Solid (lebih mahal, lebih awet), Besi/Baja (untuk rangka/kaki), atau kaca (untuk top table). Dimensi Standar Panjang umumnya 100 cm hingga 140 cm. Lebar/kedalaman idealnya sekitar 60 cm untuk menampung monitor, keyboard, dan ruang menulis yang cukup. Tinggi standar internasional adalah 75 cm. Fitur Ergonomis Tinggi yang tetap standar (75 cm) atau model adjustable (standing desk) yang dapat diatur ketinggiannya secara elektrik atau manual. Penyimpanan Dilengkapi laci, rak, atau kompartemen penyimpanan untuk menjaga area kerja tetap rapi. Opsi lain adalah meja polos tanpa laci. Manajemen Kabel Beberapa model memiliki lubang kabel (grommet) atau saluran khusus untuk merapikan kabel komputer dan perangkat lain. Finishing Melamine atau HPL (High Pressure Laminate) adalah finishing yang umum digunakan karena tahan gores, tahan air, dan mudah dibersihkan. Daya Tahan Rangka yang kokoh (terutama jika dari besi/baja) dan bahan top table yang padat menjamin umur panjang dan kemampuan menahan beban peralatan kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 862050);
