INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63328386', 63328386, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'DINAS KESEHATAN', 'BELANJA PERENCANAAN MODAL GEDUNG DAN BANGUNAN BLUD PUSKESMAS GAYAMSARI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Tengah, Semarang (Kota)', 30000000, 'May 2026', 'BLUD', 1, 1, '1 PAKET', 'BELANJA PERENCANAAN MODAL GEDUNG DAN BANGUNAN BLUD PUSKESMAS GAYAMSARI', 'Perencanaan modal untuk pembangunan gedung Puskesmas di tahun 2026 wajib mengacu pada kombinasi regulasi teknis dari Kementerian PUPR (terkait struktur bangunan negara) dan Kementerian Kesehatan (terkait fungsi layanan medis). Berikut adalah detail spesifikasi perencanaan modal untuk pembangunan gedung Puskesmas menurut standar tersebut: 1. Klasifikasi dan Biaya Bangunan (Standar PUPR) Menurut Permen PUPR No. 22/PRT/M/2018, Puskesmas umumnya dikategorikan sebagai Bangunan Gedung Negara Tidak Sederhana karena memiliki kompleksitas teknis fungsional khusus. Biaya Standar: Dihitung berdasarkan Harga Satuan Tertinggi (HST) Bangunan Gedung Negara yang ditetapkan pemerintah daerah setempat untuk tahun 2026. Biaya Non-Standar: Mencakup biaya untuk perizinan (PBG/SLF), instalasi pengolahan limbah (IPAL), penyediaan gas medis, dan sistem informasi kesehatan. Sertifikat Laik Fungsi (SLF): Perencanaan harus memastikan bangunan memenuhi syarat untuk mendapatkan SLF sebagai bukti keamanan struktur dan fasilitas sebelum beroperasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 863488);
