INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63329622', 63329622, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN LANJUTAN', 'Pengadaan Alat Kesehatan dan Meubelair RS UPT Vertikal Riau', 'Barang', 'E-Purchasing', 'Riau, Pekanbaru (Kota)', 200000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 Paket', 'Kegiatan ini merupakan pengadaan alat kesehatan untuk mendukung operasional RS UPT Vertikal Riau sebagai Rumah Sakit Tipe A dengan pengembangan awal sebanyak 351 tempat tidur. Pengadaan disusun untuk menunjang pelayanan kesehatan penyakit prioritas, khususnya jantung, stroke, dan uro-nefrologi pada strata layanan utama, guna memperkuat penyelenggaraan pelayanan rujukan nasional serta mendukung Pemerintah Daerah dan Dinas Kesehatan Provinsi/Kabupaten/Kota. Perencanaan alat kesehatan mengacu pada Keputusan Menteri Kesehatan Nomor HK.01.07/MENKES/1277/2024 serta Pedoman Teknis Peralatan Kesehatan Layanan Jantung, Stroke, dan Uro-nefrologi Tahun 2023. Prioritas pengadaan meliputi alat kesehatan layanan umum, alat dasar, serta alat kesehatan berteknologi tinggi yang memerlukan instalasi dan harus dipasang terintegrasi dengan proses pembangunan rumah sakit.', '- Spesifikasi teknis detail mengacu pada Keputusan Menteri Kesehatan Nomor HK.01.07/MENKES/1277/2024 dan Pedoman Teknis Peralatan Kesehatan Layanan Jantung, Stroke, dan Uro-nefrologi Tahun 2023 serta ketentuan peraturan perundang-undangan yang berlaku. - Pengadaan alat kesehatan layanan umum dan alat kesehatan khusus layanan jantung, stroke, dan uro-nefrologi untuk RS UPT Vertikal Riau, meliputi peralatan diagnostik, terapeutik, monitoring, penunjang tindakan medis, serta peralatan instalasi penunjang sesuai strata layanan utama Rumah Sakit Tipe A. - Alat kesehatan yang diadakan merupakan alat kesehatan baru, berizin edar Kemenkes, memenuhi standar keselamatan dan mutu, kompatibel dengan sistem rumah sakit, serta termasuk instalasi, pengujian fungsi, dan pelatihan pengguna sesuai kebutuhan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 864781);
