INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63311248', 63311248, 'analyze_legacy', 'Kab. Kulon Progo', 'kabkota', 'Dinas Pendidikan Pemuda dan Olahraga', 'Penilaian Kerusakan Bangunan PAUD 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Kulon Progo (Kab.)', 25000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Lingkup pekerjaan dalam penilaian kerusakan bangunan sekolah mencakup beberapa aspek berikut: 1. Pengumpulan Data Awal - Identifikasi lokasi dan kondisi umum bangunan sekolah. - Pengumpulan dokumen teknis seperti gambar bangunan - spesifikasi material, dan riwayat pemeliharaan. - Wawancara dengan pihak sekolah terkait kondisi bangunan dan riwayat perbaikannya. 2. Inspeksi Visual dan Dokumentasi Kerusakan - Observasi langsung terhadap elemen bangunan, termasuk atap, dinding, lantai, struktur, dan fasilitas pendukung. - Identifikasi jenis dan tingkat kerusakan, seperti retak, keropos, korosi, atau kebocoran. - Pendokumentasian melalui foto dan catatan lapangan. 3. Pengujian dan Pengukuran - Pengukuran dimensi bangunan dan elemen structural yang terdampak. - Pengujian material jika diperlukan, seperti uji kuat tekan beton atau uji kelembaban dinding. 4. Analisis dan Evaluasi Kerusakan. - Klasifikasi tingkat keparahan kerusakan (ringan, sedang, berat). - Analisis penyebab utama kerusakan, baik dari faktor lingkungan, usia bangunan, maupun kesalahan konstruksi. 5. Penyusunan Laporan dan Rekomendasi - Penyusunan laporan hasil inspeksi yang mencakup kondisi bangunan, jenis kerusakan, serta analisis penyebabnya. - Rekomendasi langkah perbaikan, rehabilitasi, atau penggantian bagian bangunan yang rusak. - Estimasi anggaran dan prioritas perbaikan berdasarkan tingkat urgensi. 6. Pelaporan dan Koordinasi dengan Pihak Terkait - Presentasi hasil penilaian kepada pihak sekolah, dinas pendidikan, atau instansi terkait. - Koordinasi untuk tindak lanjut perbaikan atau pengusulan anggaran rehabilitasi. Lingkup pekerjaan ini bertujuan untuk memastikan bahwa bangunan sekolah tetap aman, fungsional, dan mendukung proses belajar mengajar secara optimal.', 'Spesifikasi Di KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 868691);
